bounded_host_request.command:
set -euo pipefail
stage="$(mktemp -d /tmp/gaybbs-video-repin-XXXXXX)"
trap 'rm -rf "$stage"' EXIT
docker cp deploy-gaybbs-1:/app/repairTwoVideoChatPinnedEntries.mjs "$stage/base.mjs"
python3 - "$stage/base.mjs" "$stage/fixed.mjs" <<'PY'
import pathlib,re,sys
src=pathlib.Path(sys.argv[1]).read_text()
pat=r'callback_data\s*:\s*buttonCallback\s*,\s*style\s*:\s*["\']primary["\']'
if len(re.findall(pat,src))!=3:sys.exit(81)
out=re.sub(pat,'url: "https://t.me/GayBBS_bot?start=p_" + token',src)
needle=r'console\.log\(["\']VIDEO_ENTRY_FIXED["\']\s*,'
if len(re.findall(needle,out))!=1:sys.exit(82)
addition="""try {
  await bot.telegram.pinChatMessage(t.chatId,result.messageId,{disable_notification:true});
} catch(e) {
  const response=e?.response;
  if(response?.error_code!==400||!/already pinned/i.test(response?.description??""))throw e;
}
"""
out=re.sub(needle,lambda m:addition+m.group(),out)
if len(re.findall(r'await bot\.telegram\.pinChatMessage\(t\.chatId,result\.messageId',out))!=1:sys.exit(83)
pathlib.Path(sys.argv[2]).write_text(out)
PY
docker exec -i deploy-gaybbs-1 node --check --input-type=module - < "$stage/fixed.mjs"
docker exec -i -e VIDEO_TWO_TOPIC_ENTRY_APPLY=enabled -e VIDEO_TWO_TOPIC_RECOVER_GAY_ONLY=disabled deploy-gaybbs-1 node --import /app/preload/telegram-ipv4-preload.mjs --input-type=module - < "$stage/fixed.mjs"
echo TWO_TOPIC_DIRECT_DM_REPIN=PASS
